import { readFileSync } from 'node:fs'
import { defineConfig } from 'vite'
import vue from '@vitejs/plugin-vue'
import { fileURLToPath, URL } from 'node:url'

/**
 * The local development certificate, generated by `npm run dev` / `cert:dev`.
 * `vite build` also loads this config, so a missing certificate falls back to
 * HTTP instead of breaking the production build.
 */
function devCertificate(): { cert: Buffer; key: Buffer } | undefined {
  try {
    return {
      cert: readFileSync(fileURLToPath(new URL('./.cert/dev.crt', import.meta.url))),
      key: readFileSync(fileURLToPath(new URL('./.cert/dev.key', import.meta.url))),
    }
  } catch {
    return undefined
  }
}

export default defineConfig({
  // Relative asset URLs: the same build works from a domain root and from a
  // project subpath such as https://<user>.github.io/<repo>/.
  base: './',
  plugins: [vue()],
  resolve: {
    alias: {
      '@': fileURLToPath(new URL('./src', import.meta.url)),
    },
  },
  build: {
    target: 'es2022',
    chunkSizeWarningLimit: 1200,
    rollupOptions: {
      output: {
        manualChunks: {
          three: ['three'],
        },
      },
    },
  },
  server: {
    port: 5173,
    // Listen on every interface so phones, headsets and other machines on the
    // network can reach the dev server. Open the printed Network URL.
    host: true,
    // The dev server is intentionally exposed beyond localhost. This also lets
    // a tunnel or LAN hostname reach it without Vite's host-header rejection.
    allowedHosts: true,
    https: devCertificate(),
    fs: {
      // Never serve the development key or certificate as static files.
      deny: ['.env', '.env.*', '*.{crt,pem}', '**/.git/**', '**/.cert/**'],
    },
  },
  test: {
    // Live API integration tests live in tests/integration and are opt-in:
    // they consume API quota, so they only run with `npm run test:api`.
    include: ['tests/**/*.test.ts'],
    exclude: ['**/node_modules/**', '**/dist/**', 'tests/integration/**'],
  },
})
